const LOGIN_CONNECTION_OPTIONS=[{command:`vercel`,commandOrder:0,value:`vercel`,label:`Vercel Account`},{command:`vercel-api-key`,commandOrder:2,value:`ai-gateway-key`,label:`Vercel AI Gateway API Key`},{command:`chatgpt`,commandOrder:1,value:`chatgpt`,label:`ChatGPT Subscription`},{command:`openai-api-key`,commandOrder:3,value:`openai`,label:`OpenAI API Key`},{command:`anthropic-api-key`,commandOrder:4,value:`anthropic`,label:`Anthropic API Key`}],CONNECTION_OPTIONS=LOGIN_CONNECTION_OPTIONS.map(({value:e,label:t})=>({value:e,label:t})),LOGIN_CONNECTION_COMMAND_OPTIONS=[...LOGIN_CONNECTION_OPTIONS].sort((e,t)=>e.commandOrder-t.commandOrder);function loginConnectionForCommand(e){return LOGIN_CONNECTION_OPTIONS.find(t=>t.command===e)?.value}const LOGIN_CONNECTION_COMMAND_HINT=LOGIN_CONNECTION_COMMAND_OPTIONS.map(e=>e.command).join(`|`);export{CONNECTION_OPTIONS,LOGIN_CONNECTION_COMMAND_HINT,LOGIN_CONNECTION_COMMAND_OPTIONS,LOGIN_CONNECTION_OPTIONS,loginConnectionForCommand};